alter table public.products add column if not exists updated_at timestamptz not null default now(); alter table public.arrivals add column if not exists updated_at timestamptz not null default now(); create or replace function public.touch_updated_at() returns trigger language plpgsql set search_path='' as $$ begin new.updated_at=now(); return new; end $$; create trigger products_touch_updated_at before update on public.products for each row execute function public.touch_updated_at(); create trigger arrivals_touch_updated_at before update on public.arrivals for each row execute function public.touch_updated_at();
